mapper.sql:
WHERE B.DEL_DT IS NULL AND B.EXPSR_YN = 'Y'
AND B.RCMDTN_YN = 'Y'
AND B.RCMDTN_CLSF_CD = #{category}
AND B.NEW_BOOK_YR IS NOT NULL AND B.NEW_BOOK_YR != ''
AND B.NEW_BOOK_YR = #{newBookYear}
AND B.NEW_BOOK_MM = #{newBookMonth}
AND B.BOOK_NM LIKE CONCAT('%', #{keyword}, '%')
AND B.BOOK_CN LIKE CONCAT('%', #{keyword}, '%')
AND ( B.BOOK_NM LIKE CONCAT('%', #{keyword}, '%') OR B.BOOK_CN LIKE CONCAT('%', #{keyword}, '%') OR B.AUT_NM LIKE CONCAT('%', #{keyword}, '%') OR B.PBLCO_NM LIKE CONCAT('%', #{keyword}, '%') )
